using System;using System.Drawing;using System.Globalization;using System.IO;using System.Windows.Forms;
namespace ScoreModern { public sealed partial class Editor {
 string preferenceSerialKey,preferenceSerialPath;
 string PreferenceSerialPath(){string key=NativeLibraryLocation.CacheKey(source)+"|"+NativeSettings.Read("dat");if(preferenceSerialKey!=key){preferenceSerialPath=NativeScoreIdentity.Require(source,false).Path;preferenceSerialKey=key;}return preferenceSerialPath;}
 sealed class PreferenceValue {
  internal string Label,Units="",EnableSetting,Help="",Filter="All files|*.*";internal bool Folder,File;internal Func<bool> Active;internal Action<bool> Activate;internal Func<string> Read;internal Action<string> Write;
 }
 PreferenceValue NumberPreference(string label,Func<double> read,Action<double> write,double min,double max,string units,string enable=null){return new PreferenceValue{Label=label,Read=()=>read().ToString("0.##",CultureInfo.InvariantCulture),Write=s=>{double v;if(!Double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out v)||Double.IsNaN(v)||Double.IsInfinity(v)||v<min||v>max)throw new ArgumentException("Enter "+min+" to "+max+" "+units+".");write(v);},Units=units,EnableSetting=enable,Help="Range: "+min+"–"+max+" "+units+". Press Enter or leave the field to apply."};}
 PreferenceValue InlinePreference(string text){
  if(text.StartsWith("Startup: title screen duration"))return NumberPreference("Title screen duration",()=> (double)NativeStartupSplash.DurationSeconds,v=>NativeStartupSplash.SetDuration((decimal)v),0,60,"seconds","Startup: original SCORE title splash");
  if(text=="Text area font size...")return NumberPreference("Text area font size",()=>textAreaFontPoints==0?12:textAreaFontPoints,v=>SetTextAreaFontSize((float)v,true),6,24,"points");
  if(text=="Choose serial DAT...")return new PreferenceValue{Label="Serial-bearing DAT",File=true,Filter="SCORE DAT files|*.DAT|All files|*.*",Read=()=>PreferenceSerialPath(),Write=s=>{string folder=Path.GetDirectoryName(Path.GetFullPath(s)),active=Path.GetFullPath(NativeLibraryLocation.DirectoryFor(source,false));if(!String.Equals(folder.TrimEnd('\\','/'),active.TrimEnd('\\','/'),StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Choose a verified DAT inside the active resource LIB folder.");NativeScoreIdentity.Select(folder,s,true);var choice=NativeLibraryLocation.Get(source);ApplyLibraryFolder(choice==null?null:choice.Folder,choice!=null&&choice.All,false);},Help="Verified serial-bearing DAT in the resource LIB. Supplies SCORE identity and packed screen resources. Only the filename is displayed; the contained serial is not shown."};
  if(text.StartsWith("Font initialisation: external"))return new PreferenceValue{Label="External FONTINIT.PSC",File=true,Read=()=>NativeSettings.Read("fontinit-path")??NativeLibraryLocation.FileFor(source,"FONTINIT.PSC"),Write=s=>{NativeFontInitialization.Parse(System.IO.File.ReadAllText(s,System.Text.Encoding.GetEncoding(28591)));NativeSettings.WriteAllText("fontinit-path",System.IO.Path.GetFullPath(s));NativeFontInitialization.Set(true,true);RefreshAll(canvas.Selected);},Active=()=>NativeFontInitialization.External,Activate=v=>{NativeFontInitialization.Set(v,true);RefreshAll(canvas.Selected);},Help="External PostScript font-initialisation procedures. Default: FONTINIT.PSC in the active LIB. Only supported original procedure definitions are accepted; an explicitly selected path overrides the LIB path."};
  if(text=="Use external VGA font...")return new PreferenceValue{Label="External VGA interface font",File=true,Read=()=>NativeInterfaceText.VgaPath??"",Write=s=>NativeInterfaceText.SetVga(s,true),Active=()=>NativeInterfaceText.UseVga,Activate=v=>{if(v)NativeInterfaceText.SetVga(NativeInterfaceText.VgaPath??"",true);else NativeInterfaceText.SetConsolas(true);}};
  if(text.StartsWith("Ghostscript (external helper)"))return new PreferenceValue{Label="Ghostscript console executable",File=true,Read=()=>GhostscriptTextRenderer.Executable,Write=s=>{if(!System.IO.File.Exists(s))throw new FileNotFoundException("Choose an existing Ghostscript console executable.");GhostscriptTextRenderer.Configure(true,s,true);},Active=()=>GhostscriptTextRenderer.Enabled,Activate=v=>{if(v&&!System.IO.File.Exists(GhostscriptTextRenderer.Executable))throw new FileNotFoundException("Choose an existing Ghostscript console executable first.");GhostscriptTextRenderer.Configure(v,null,true);}};
  if(text.StartsWith("TAB: DOS load segment"))return new PreferenceValue{Label="TAB DOS load segment",Units="hex",Read=()=>NativeTabEnvironment.LoadSegment.ToString("X4"),Write=s=>{ushort n;if(!UInt16.TryParse(s,NumberStyles.HexNumber,CultureInfo.InvariantCulture,out n))throw new ArgumentException("Enter hexadecimal 0000–FFFF.");NativeTabEnvironment.SetLoadSegment(n);},Help="Only affects SCORE's address-dependent TAB quarter-tone calculations. 0824 matches the measured DOSBox-X reference; this is a simulated DOS address, never a Windows pointer."};
  if(text=="Recent files shown...")return NumberPreference("Recent files",()=>NativeRecentFiles.Count,v=>{if(v!=(int)v)throw new ArgumentException("Enter a whole number.");NativeSettings.WriteAllText("recent-file-count",v.ToString(CultureInfo.InvariantCulture));},0,50,"files");
  if(text.StartsWith("Notation gap size"))return NumberPreference("Notation boundary gap",()=>NativeWorkspaceGuides.GapPoints,v=>SetGuideValue("notation-gap-points",v,()=>NativeWorkspaceGuides.GapPoints=(float)v),0,720,"points","Gap around outermost notation");
  if(text.StartsWith("Page gap size"))return NumberPreference("Page boundary gap",()=>NativeWorkspaceGuides.PageGapPoints,v=>SetGuideValue("page-gap-points",v,()=>NativeWorkspaceGuides.PageGapPoints=(float)v),0,720,"points","Gap around page");
  if(text.StartsWith("Horizontal ruler height"))return NumberPreference("Horizontal ruler height",()=>NativeWorkspaceGuides.RulerHeight,v=>SetGuideValue("ruler-height",v,()=>NativeWorkspaceGuides.RulerHeight=(float)v),40,160,"logical pixels","Show margin rulers");
  if(text.StartsWith("Vertical ruler width"))return NumberPreference("Vertical ruler width",()=>NativeWorkspaceGuides.RulerWidth,v=>SetGuideValue("ruler-width",v,()=>NativeWorkspaceGuides.RulerWidth=(float)v),24,160,"logical pixels","Show margin rulers");
  if(text=="Type 1 fonts...")return new PreferenceValue{Label="Type 1 font folder",Folder=true,Read=()=>NativeTupletFonts.DirectoryPath??"",Write=s=>{RequirePreferenceFolder(s);NativeTupletFonts.SetDirectory(s,true);QueuePscOfferAfterFontSelection();}};
  if(text=="Browse for LIB folder...")return new PreferenceValue{Label="Drawing LIB folder",Folder=true,Read=()=>NativeLibraryLocation.DirectoryFor(source,true),Write=s=>{RequirePreferenceFolder(s);var c=NativeLibraryLocation.Get(source);ApplyLibraryFolder(s,c!=null&&c.All,true);}};
  if(text=="Startup SCORE folder...")return new PreferenceValue{Label="Startup folder",Folder=true,Read=()=>NativeStartupFolder.Preferred,Write=s=>{RequirePreferenceFolder(s);NativeStartupFolder.Save(s);}};
  if(text=="Save and export folder...")return new PreferenceValue{Label="Save / export folder",Folder=true,Read=()=>NativeOutputLocation.Folder(source),Write=s=>NativeOutputLocation.SetFolder(source,s)};
  if(text=="Interface text: choose UI font...")return new PreferenceValue{Label="Interface font family",Read=()=>NativeUiFont.Family,Write=s=>{NativeUiFont.Set(s,true);NativeInterfaceText.SetConsolas(true);},Help="Installed Windows font family used for interface text only; notation keeps its Type 1 metrics."};
  return null;
 }
 static void RequirePreferenceFolder(string path){if(!Path.IsPathRooted(path)||!Directory.Exists(path))throw new DirectoryNotFoundException("Enter an existing absolute folder path.");}
 void SetGuideValue(string key,double value,Action update){NativeSettings.WriteAllText(key,value.ToString(CultureInfo.InvariantCulture));update();RefreshPageFrame();}
 string CompatibilityHelp(ToolStripMenuItem item){string t=item.Text,detail=item.ToolTipText??"";
  if(detail.Length>=80)return detail+"\n\nStrict SCORE mode overrides alternative operations while preserving your saved choices and native display quality.";
  if(t.StartsWith("Keyboard: Item PgUp"))detail="Moves the active item's selected coordinate by 4 units in the measured executable. Tom's Help alternatives use 5 or 10. Does not pan the page in item edit.";
  else if(t.StartsWith("Keyboard: Item Tab"))detail="Tab and Shift+Tab move the active item horizontally by 10 SCORE units in the executable; the Help alternative uses 5. The file changes only when the edit is committed.";
  else if(t.StartsWith("Mouse selection: original unrestricted"))detail="Uses SCORE's nearest-anchor search without a maximum click distance. An empty-space click may therefore select a distant item. Off limits selection to nearby items; original coordinate quantisation is a separate choice.";
  else if(t.StartsWith("Mouse selection:"))detail="Original DOS grid converts the pointer to SCORE's integer 640×480 coordinates before its recovered anchor-distance calculation. High-resolution distances keep fractional positions and can select a different item near a boundary.";
  else if(t.StartsWith("Grace-chord flips:"))detail="Choose the recovered deterministic grace-chord stem calculation or reproduce the executable's retained scratch-word effects, where earlier operations can change the result for the same chord.";
  else if(t.StartsWith("Editing:"))detail="Controls reproduction of original invalid edit states and buffer effects. The safe default prevents invalid item-zero navigation; original reproduction can retain the executable's unusable states. It does not change valid notation rules.";
  else if(t.StartsWith("Slurs: reject")||t.StartsWith("Slurs and hairpins: reject"))detail="Rejects reversed and out-of-range trims instead of reproducing the original's backwards buffer movement or reads from neighbouring buffered items. Normal trim ranges are unchanged.";
  else if(t.StartsWith("Endings:"))detail="Selects Tom's Help interpretation of P8=10 as an ending, instead of the measured executable's slur branch for that integer value. Other P8 ending values retain the recovered behaviour.";
  else if(t.StartsWith("Justification:"))detail="Quarter-tone accidentals 106–109 can use the documented widths of symbols 6–9. Original reproduction retains the measured out-of-table width reads, which can depend on the DOS memory state.";
  else if(t.StartsWith("DPY:"))detail="Chooses original bounded DOS buffer handling or the native array extension. The extension permits data beyond the original capacity and is not an equivalence claim.";
  else if(t.StartsWith("Beams/slurs:"))detail="Selects the original printed/EPS geometry or the original DOS screen geometry. Both are recovered SCORE paths; their thickness, rounding and some positions differ.";
  else if(t.StartsWith("Preferences:"))detail="Maps DOS resource paths from PREF.SCR into the chosen SCORE installation. Explicit folder selections take precedence. Turning this off uses the selected resource folders instead.";
  else if(detail.Length==0)detail="Changes "+t.TrimEnd('.','…')+". The displayed value is effective now; disabled controls are overridden by Strict SCORE behaviour or unavailable in the current configuration.";
  return detail+"\n\nStrict SCORE behaviour preserves native Windows/4K rendering while enforcing the recovered SCORE operation. Individual alternative choices are retained and restored when Strict mode is switched off; it does not certify unverified commands.";
 }
 }
}
